struct VersionComparator {
    static func isBuildEligible(current: Int, previous: Int) -> Bool {
        return current > previous
    }
}

let res1 = VersionComparator.isBuildEligible(current: 45, previous: 44)
let res2 = VersionComparator.isBuildEligible(current: 45, previous: 45)
print("Eligibility: \(res1 && !res2)")

struct ProfileClassifier {
    func requiresUDIDRegistration(profileType: String) -> Bool {
        return profileType == "development" || profileType == "adHoc"
    }
}

let classifier = ProfileClassifier()
let devCheck = classifier.requiresUDIDRegistration(profileType: "development")
let storeCheck = classifier.requiresUDIDRegistration(profileType: "appStore")
print("Classifier check: \(devCheck && !storeCheck)")

class PhasedReleaseScheduler {
    func percentageForDay(day: Int) -> Int {
        if day < 1 { return 0 }
        switch day {
        case 1: return 1
        case 2: return 2
        case 3: return 5
        case 4: return 10
        case 5: return 20
        case 6: return 50
        default: return 100
        }
    }
}

let scheduler = PhasedReleaseScheduler()
print("Rollout day 1: \(scheduler.percentageForDay(day: 1))%, day 4: \(scheduler.percentageForDay(day: 4))%, day 7: \(scheduler.percentageForDay(day: 7))%")
